package handshake

import "testing"

// FuzzServerHelloKeyShareGroup feeds arbitrary bytes to the ServerHello parser
// added by ECHOFOG-PATCH.md patch 3. Every input must return, never panic.
func FuzzServerHelloKeyShareGroup(f *testing.F) {
	// A minimal ServerHello carrying one X25519 key share.
	f.Add([]byte{
		0x02, 0x00, 0x00, 0x30, // handshake header: server_hello, 48 bytes
		0x03, 0x03, // legacy_version
		0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // random (32 bytes)
		0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
		0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
		0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
		0x00,       // empty session_id
		0x13, 0x01, // cipher suite
		0x00,       // compression
		0x00, 0x08, // extensions length
		0x00, 0x33, 0x00, 0x04, // key_share, 4 bytes
		0x00, 0x1d, // X25519
		0x00, 0x00, // empty key exchange
	})
	f.Add([]byte{})
	f.Add([]byte{0x02, 0x00, 0x00, 0x00})
	f.Fuzz(func(t *testing.T, msg []byte) {
		_, _ = serverHelloKeyShareGroup(msg)
	})
}
